/* SEMAFORO V4 - Arduino Uno
   D8 rojo, D9 amarillo, D10 verde.
   D2: interruptor entre D2 y GND.
   D2 abierto (HIGH por INPUT_PULLUP): ciclo autonomo.
   D2 cerrado (LOW): control recibido desde la web por USB Serial.
   USB Serial 115200 baudios. Comandos R/Y/G + salto de linea.
*/
const byte LED_R=8, LED_Y=9, LED_G=10, SELECTOR=2;
enum Light { RED, YELLOW, GREEN };
Light currentLight=RED;
unsigned long phaseStarted=0;
const unsigned long durations[]={5000,2000,5000};
byte phase=0;
bool webMode=false;
bool lastWebMode=false;
String inputLine;
void show(Light l){currentLight=l;digitalWrite(LED_R,l==RED);digitalWrite(LED_Y,l==YELLOW);digitalWrite(LED_G,l==GREEN);}
void reportMode(){Serial.println(webMode?"MODE:WEB":"MODE:AUTO");}
void setup(){pinMode(LED_R,OUTPUT);pinMode(LED_Y,OUTPUT);pinMode(LED_G,OUTPUT);pinMode(SELECTOR,INPUT_PULLUP);Serial.begin(115200);show(RED);phase=0;phaseStarted=millis();webMode=(digitalRead(SELECTOR)==LOW);reportMode();}
void loop(){
  bool selectedWeb=(digitalRead(SELECTOR)==LOW);
  if(selectedWeb!=webMode){webMode=selectedWeb;show(RED);phase=0;phaseStarted=millis();reportMode();}
  while(Serial.available()){
    char c=Serial.read();
    if(c=='\n'||c=='\r'){
      if(inputLine.length()){
        if(webMode){char cmd=inputLine.charAt(0);if(cmd=='R'||cmd=='r')show(RED);else if(cmd=='Y'||cmd=='y')show(YELLOW);else if(cmd=='G'||cmd=='g')show(GREEN);Serial.print("ACK:");Serial.println(cmd);}
        inputLine="";
      }
    }else if(inputLine.length()<12)inputLine+=c;
  }
  if(!webMode){unsigned long now=millis();if(now-phaseStarted>=durations[phase]){phase=(phase+1)%3;phaseStarted=now;show((Light)phase);}}
}
